import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    keys = []
    seen = {}
    for i in range(n):
        base = 1 + 4 * i
        key = (data[base], data[base + 1], data[base + 2])
        ts = int(data[base + 3])
        keys.append(key)
        s = seen.get(key)
        if s is None:
            seen[key] = {ts}
        else:
            s.add(ts)
    res = [str(i) for i in range(n) if len(seen[keys[i]]) >= 2]
    print(' '.join(res) if res else -1)

