    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] senders = new String[n], receivers = new String[n];
        long[] amounts = new long[n], timestamps = new long[n];
        for (int i = 0; i < n; i++) {
            senders[i] = st.nextToken();
            receivers[i] = st.nextToken();
            amounts[i] = Long.parseLong(st.nextToken());
            timestamps[i] = Long.parseLong(st.nextToken());
        }
        int[] res = findDuplicates(senders, receivers, amounts, timestamps);
        if (res.length == 0) {
            System.out.println(-1);
            return;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
